import { ISerialisedError } from './types';
import { serialise } from './serialiser';

declare global {
    interface Error {
        data?: any;
        serialise: () => ISerialisedError;
    }
}

Error.prototype.serialise = function () {
    return serialise(this);
};

export * from './base-exception';
export * from './exception-types';
export * from './constants';
export * from './types';
